use serde::{Deserialize,Serialize};use sha2::{Digest,Sha256};use std::collections::{BTreeMap,BTreeSet};
#[derive(Deserialize,Clone)]pub struct Artifact{pub path:String,pub content:String,#[serde(default)]pub dependencies:Vec<String>,#[serde(default)]pub contracts:Vec<String>}
#[derive(Deserialize)]pub struct Request{pub candidate_id:String,pub baseline:Vec<Artifact>,pub candidate:Vec<Artifact>,#[serde(default)]pub requirements:Vec<String>,#[serde(default)]pub requirement_links:BTreeMap<String,Vec<String>>,#[serde(default)]pub allowed_paths:Vec<String>,#[serde(default)]pub required_contracts:Vec<String>,#[serde(default)]pub known_candidate_hashes:Vec<String>,#[serde(default)]pub manifest:serde_json::Value}
#[derive(Serialize)]pub struct Diff{pub added:Vec<String>,pub modified:Vec<String>,pub removed:Vec<String>}
#[derive(Serialize)]pub struct Trace{pub requirement:String,pub artifacts:Vec<String>,pub covered:bool}
#[derive(Serialize)]pub struct Issue{pub code:&'static str,pub detail:String}
#[derive(Serialize)]pub struct ResultData{pub structural_diff:Diff,pub traceability:Vec<Trace>,pub contract_valid:bool,pub scope_valid:bool,pub dependency_graph:BTreeMap<String,Vec<String>>,pub structure_sha256:String,pub duplicate_candidate:bool,pub evidence_bundle:serde_json::Value,pub manifest_valid:bool,pub issues:Vec<Issue>,pub engine:&'static str,pub owner_domain:&'static str,pub receipt_version:u32}
fn hash_text(v:&str)->String{Sha256::digest(v.as_bytes()).iter().map(|b|format!("{b:02x}")).collect()}
fn canonical_hash(items:&[Artifact])->String{let mut rows=items.iter().map(|a|serde_json::json!({"path":a.path,"sha256":hash_text(&a.content),"dependencies":a.dependencies,"contracts":a.contracts})).collect::<Vec<_>>();rows.sort_by(|a,b|a["path"].as_str().cmp(&b["path"].as_str()));hash_text(&serde_json::to_string(&rows).unwrap_or_default())}
pub fn analyze_json(source:&str)->Result<String,String>{let r:Request=serde_json::from_str(source).map_err(|e|format!("SELF_DEVELOPMENT_JSON:{e}"))?;if r.candidate.len()>200_000{return Err("CANDIDATE_ARTIFACT_LIMIT".into())}let base:BTreeMap<_,_>=r.baseline.iter().map(|a|(a.path.clone(),a)).collect();let cand:BTreeMap<_,_>=r.candidate.iter().map(|a|(a.path.clone(),a)).collect();let mut added=Vec::new();let mut modified=Vec::new();let mut removed=Vec::new();for(path,item)in &cand{match base.get(path){None=>added.push(path.clone()),Some(old)if hash_text(&old.content)!=hash_text(&item.content)=>modified.push(path.clone()),_=>{}}}for path in base.keys(){if !cand.contains_key(path){removed.push(path.clone())}}let links=r.requirement_links;let traceability=r.requirements.iter().map(|req|{let artifacts=links.get(req).cloned().unwrap_or_default();let covered=!artifacts.is_empty()&&artifacts.iter().all(|p|cand.contains_key(p));Trace{requirement:req.clone(),artifacts,covered}}).collect::<Vec<_>>();let candidate_contracts:BTreeSet<_>=r.candidate.iter().flat_map(|a|a.contracts.iter().cloned()).collect();let missing_contracts=r.required_contracts.iter().filter(|c|!candidate_contracts.contains(*c)).cloned().collect::<Vec<_>>();let changed=added.iter().chain(modified.iter()).chain(removed.iter()).cloned().collect::<Vec<_>>();let scope_valid=r.allowed_paths.is_empty()||changed.iter().all(|p|r.allowed_paths.iter().any(|root|p.starts_with(root)));let graph=r.candidate.iter().map(|a|(a.path.clone(),a.dependencies.clone())).collect::<BTreeMap<_,_>>();let structure_sha256=canonical_hash(&r.candidate);let duplicate_candidate=r.known_candidate_hashes.contains(&structure_sha256);let manifest_hash=r.manifest.get("structure_sha256").and_then(|v|v.as_str()).unwrap_or("");let manifest_id=r.manifest.get("candidate_id").and_then(|v|v.as_str()).unwrap_or("");let manifest_valid=manifest_hash==structure_sha256&&manifest_id==r.candidate_id;let mut issues=Vec::new();for t in &traceability{if !t.covered{issues.push(Issue{code:"REQUIREMENT_UNCOVERED",detail:t.requirement.clone()})}}for c in &missing_contracts{issues.push(Issue{code:"CONTRACT_MISSING",detail:c.clone()})}if !scope_valid{issues.push(Issue{code:"CHANGE_SCOPE_VIOLATION",detail:changed.join(",")})}for(a,deps)in &graph{for dep in deps{if !cand.contains_key(dep){issues.push(Issue{code:"DEPENDENCY_TARGET_MISSING",detail:format!("{a}->{dep}")})}}}if duplicate_candidate{issues.push(Issue{code:"CANDIDATE_DUPLICATE",detail:structure_sha256.clone()})}if !manifest_valid{issues.push(Issue{code:"EVALUATION_MANIFEST_MISMATCH",detail:r.candidate_id.clone()})}let evidence_bundle=serde_json::json!({"candidate_id":r.candidate_id,"structure_sha256":structure_sha256,"changed_paths":changed,"requirements_covered":traceability.iter().filter(|t|t.covered).count(),"requirements_total":traceability.len(),"contracts":candidate_contracts,"manifest_valid":manifest_valid});let result=ResultData{structural_diff:Diff{added,modified,removed},traceability,contract_valid:missing_contracts.is_empty(),scope_valid,dependency_graph:graph,structure_sha256,duplicate_candidate,evidence_bundle,manifest_valid,issues,engine:"RUST",owner_domain:"selfDevelopment",receipt_version:1};serde_json::to_string(&result).map_err(|e|format!("SELF_DEVELOPMENT_RESULT:{e}"))}

#[cfg(test)]
mod tests { use super::*;
 #[test] fn uncovered_requirement_is_reported(){let x=r#"{"candidate_id":"C1","baseline":[],"candidate":[],"requirements":["REQ-1"],"manifest":{}}"#;assert!(analyze_json(x).unwrap().contains("REQUIREMENT_UNCOVERED"));}
}
